fn prime_num(n: u64) -> bool {
    // Since n >= 2, handle the smallest prime explicitly:
    if n == 2 {
        return true;
    }

    // If n is even and greater than 2, it's not prime:
    if n % 2 == 0 {
        return false;
    }

    // Check divisors from 3 up to sqrt(n), stepping by 2 (only odd numbers):
    let limit = (n as f64).sqrt() as u64;
    for i in (3..=limit).step_by(2) {
        if n % i == 0 {
            return false;
        }
    }

    true
}